  'mesa': r'''{
 "scene": "mesa",
 "made": "node docs/proyecto/pixel/mesa-sheet-make.js, from mesa-set.html (window.MESA_SET), cocina-kit.js and coqui/ref/escenas/mesa/. Order 37a.",
