   "pila": "W.pila: \"0\", \"a\" (dishwater), \"j\" (juice)",
   "banco": "W.banco ? 1 : 0 (the stool)"
  },
  "key": "nev + \".\" + cajon + \".\" + pila + \".\" + banco",
  "baked": [
